func renderCredentialsPlanResponse(cmd *cobra.Command, flags *rootFlags, payload credentialsPlanResponse) error {
	asJSON := flags.asJSON || flags.agent || !isTerminal(cmd.OutOrStdout())
	if asJSON {
		return printJSONFiltered(cmd.OutOrStdout(), payload, flags)
	}

	w := cmd.OutOrStdout()
	if payload.Surface == "" {
		fmt.Fprintln(w, "Credentials plan")
		fmt.Fprintln(w, "Safety: local guidance only. No secret reads, credential writes, API calls, docs calls, MCP execution, publishing, signing, notarization, or launch approval.")
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Surfaces:")
		for _, surface := range payload.AvailableSurfaces {
			fmt.Fprintf(w, "  %s\n", surface)
		}
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Blockers:")
		for _, blocker := range payload.Blockers {
			fmt.Fprintf(w, "  %s\n", blocker)
		}
		return nil
	}
	if payload.Surface == "all" {
		fmt.Fprintln(w, "Credentials plan: all")
		fmt.Fprintln(w, "Safety: local guidance only. Public launch still needs credential storage decisions.")
		for _, plan := range payload.SurfacePlans {
			fmt.Fprintf(w, "  %s - %s\n", plan.Name, plan.Summary)
		}
		return nil
	}

	plan := payload.SurfacePlan
	fmt.Fprintf(w, "Credentials plan: %s\n", plan.Name)
	fmt.Fprintf(w, "Current support: %s\n", plan.CurrentSupport)
	fmt.Fprintln(w, "Launch decision needed:")
	for _, decision := range plan.LaunchDecisionNeeded {
		fmt.Fprintf(w, "  %s\n", decision)
	}
	fmt.Fprintln(w, "Blockers:")
	for _, blocker := range plan.Blockers {
		fmt.Fprintf(w, "  %s\n", blocker)
	}
	return nil
}

